import { createMemo, ParentComponent, Show, splitProps } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip, TooltipTextProps } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import style from "#base/ui-next/components/styles/line-through.scss?url";

interface TradeRouteCriteriaTooltipProps extends TooltipTextProps {
	isNegative: boolean;
	appliesToCurrentCiv: boolean;
}
const TradeRouteCriteriaTooltipComponent: ParentComponent<TradeRouteCriteriaTooltipProps> = (props) => {
	const [local, other] = splitProps(props, [
		"text",
		"args",
		"children",
		"header",
		"isNegative",
		"appliesToCurrentCiv",
	]);

	const isNegativeOrDoesNotApply = createMemo(() => local.isNegative || !local.appliesToCurrentCiv);
	return (
		<Tooltip
			{...other}
			showFiligrees={false}
		>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame class={`relative flex flex-col pb-1 w-128`}>
					<Show when={local.header}>
						{(header) => (
							<div class="w-full flex items-center mb-1">
								<Icon
									class="size-6 mr-1"
									name={
										isNegativeOrDoesNotApply()
											? "url('blp:dip_esp_fail_icon')"
											: "url('blp:dip_esp_success_icon')"
									}
									isUrl={true}
								/>
								<div
									class="relativetracking-100"
									classList={{
										"text-negative decoration-negative": isNegativeOrDoesNotApply(),
										"decoration-accent-2": !isNegativeOrDoesNotApply(),
										"line-through": !local.appliesToCurrentCiv,
									}}
								>
									<L10n.Compose text={header()} />
								</div>
							</div>
						)}
					</Show>
					<L10n.Stylize
						text={local.text}
						args={local.args}
						class="relative"
					/>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const TradeRouteCriteriaTooltip = ComponentRegistry.register({
	name: "TradeRouteCriteriaTooltip",
	createInstance: TradeRouteCriteriaTooltipComponent,
	styles: [style],
	images: ["blp:dip_esp_fail_icon", "blp:dip_esp_success_icon"],
});
